.shell { display:grid; grid-template-columns:16rem minmax(0,1fr); min-height:100dvh; }
.main { min-width:0; padding:clamp(1rem,3vw,3rem); }
@media(max-width:52rem) { .shell { grid-template-columns:1fr; } .side { border-block-end:1px solid var(--border); } }

:root { --surface:#fff; --text:#15243a; --muted:#4d5c72; --accent:#2559b6; --border:#c6cfdb; --space:0.5rem; --radius:0.75rem; }
[data-theme=dark] { --surface:#111a29; --text:#edf2fa; --muted:#b5c2d5; --accent:#9bbbff; --border:#40516b; }
:focus-visible { outline:3px solid var(--accent); outline-offset:3px; }

.skeleton { background:var(--border); border-radius:var(--radius); min-height:1rem; }
@keyframes breathe { 50% { opacity:.55; } }
@media(prefers-reduced-motion:no-preference) { .skeleton { animation:breathe 1.5s ease-in-out infinite; } }

const motion = matchMedia("(prefers-reduced-motion: reduce)");
function applyMotion() {
  document.documentElement.dataset.motion = motion.matches ? "reduced" : "full";
}
applyMotion();
motion.addEventListener("change", applyMotion);

final reduce = MediaQuery.of(context).disableAnimations;
AnimatedSwitcher(
  duration: reduce ? Duration.zero : const Duration(milliseconds: 180),
  child: Text(statusLabel, key: ValueKey(statusLabel)),
);

LayoutBuilder(builder: (context, constraints) {
  final hinges = MediaQuery.of(context).displayFeatures.where(
    (f) => f.type == DisplayFeatureType.hinge &&
      f.bounds.height > f.bounds.width && f.bounds.width > 0).toList();
  if (constraints.maxWidth < 720) return buildStacked();
  if (hinges.isNotEmpty) {
    final gap = hinges.first.bounds;
    return Row(children: [
      SizedBox(width: gap.left, child: buildList()),
      SizedBox(width: gap.width), Expanded(child: buildDetail()),
    ]);
  }
  return Row(children: [Expanded(child: buildList()), Expanded(child: buildDetail())]);
});

body { font:1rem/1.6 system-ui,sans-serif; color:var(--text); }
h1 { font-size:clamp(2rem,1.2rem + 4vw,4.5rem); line-height:1.1; letter-spacing:-.025em; }
h2 { font-size:clamp(1.5rem,1rem + 2vw,2.5rem); line-height:1.2; }
p { max-width:65ch; }

async function save(button, status, persist) {
  button.disabled = true; status.textContent = "Saving…";
  try { await persist(); status.textContent = "Saved"; }
  catch { status.textContent = "Save failed. Your changes are still here; try again."; }
  finally { button.disabled = false; }
}

function announceRoute(title) {
  document.title = title;
  const heading = document.querySelector("main h1");
  if (heading) { heading.tabIndex = -1; heading.focus(); }
}

button { min-height:44px; padding:.65rem 1rem; }
@media(prefers-reduced-motion:no-preference) { button { transition:transform 100ms ease-out; } button:active:not(:disabled) { transform:scale(.98); } }
button:disabled { opacity:.65; cursor:not-allowed; }

:root { --header-height:4rem; }
header { position:sticky; top:0; z-index:10; min-height:var(--header-height); background:var(--surface); border-bottom:1px solid var(--border); }
html { scroll-padding-top:calc(var(--header-height) + 1rem); }
[id] { scroll-margin-top:calc(var(--header-height) + 1rem); }

.card-wrap { container-type:inline-size; }
.card { display:grid; gap:1rem; }
@container(min-width:32rem) { .card { grid-template-columns:8rem minmax(0,1fr); align-items:center; } }
.card img { max-width:100%; height:auto; }
